import { useEffect,useMemo,useRef,useState } from 'react';
import { useMutation,useQuery,useQueryClient } from '@tanstack/react-query';
import { Link,useSearchParams } from 'react-router-dom';
import { AlertTriangle,Check,ChevronRight,FileJson,FileKey2,KeyRound,RefreshCw,Search,ShieldCheck,UserRound,UsersRound,X } from 'lucide-react';
import { api } from '../lib/api';
import { actionCatalogue,calculateExpiry,fuzzyIdentities,fuzzyPolicies,fuzzyResources,riskForPolicies,validateApprovalDeadline,validateArnList,validatePolicyJson,type AccessDuration,type RequestPriority } from '../lib/iam';
import { canOpenWizardStep, shouldShowScheduledStartInput, unlockNextWizardStep } from '../lib/wizard';
import type { AwsResource,IamIdentity,IamPolicySummary,TargetType } from '../types';
import { useAuthStore } from '../store/auth';
import { Button, LoadingSkeleton, Modal, PageHeader, RiskBadge, TechnicalDetails } from '../components/ui';

const userRoleSteps=['Target','Permission','Resources','Access duration','Reason','Review'];
const groupSteps=['Target','Members','Permission','Resources','Access duration','Reason','Review'];
const durationOptions:AccessDuration[]=['1 hour','8 hours','1 day','7 days','30 days','Custom','Permanent'];
const priorityOptions:{value:RequestPriority;hint:string}[]=[
 {value:'Normal',hint:'Standard planned work'},
 {value:'High',hint:'Time-sensitive project or incident'},
 {value:'Urgent',hint:'Active incident or outage'}
];
const defaultPolicy=JSON.stringify({Version:'2012-10-17',Statement:[{Effect:'Allow',Action:['s3:ListBucket'],Resource:['arn:aws:s3:::example-bucket']}]},null,2);

export default function NewRequest(){
 const [params]=useSearchParams(),qc=useQueryClient();
 const session=useAuthStore(state=>state.session);
 const [step,setStep]=useState(1),[maxUnlocked,setMaxUnlocked]=useState(1),[toast,setToast]=useState<string>(),[submitted,setSubmitted]=useState<any>();
 const panelRef=useRef<HTMLElement>(null);
 const [targetType,setTargetType]=useState<TargetType>(),[target,setTarget]=useState<IamIdentity>();
 const isUser=targetType==='USER',isRole=targetType==='ROLE',isGroup=targetType==='GROUP';
 const [groupMode,setGroupMode]=useState<'CREATE'|'EXISTING'>('CREATE'),[groupName,setGroupName]=useState(''),[selectedMembers,setSelectedMembers]=useState<IamIdentity[]>([]),[groupDetailOpen,setGroupDetailOpen]=useState(false);
 const [identitySearch,setIdentitySearch]=useState(''),[includeServiceLinked,setIncludeServiceLinked]=useState(false);
 const [permissionTab,setPermissionTab]=useState<'AWS_MANAGED'|'EXISTING'|'CUSTOM'>('AWS_MANAGED');
 const [policySearch,setPolicySearch]=useState(''),[serviceFilter,setServiceFilter]=useState(''),[accessFilter,setAccessFilter]=useState(''),[riskFilter,setRiskFilter]=useState('');
 const [selectedPolicies,setSelectedPolicies]=useState<IamPolicySummary[]>([]),[selectedExisting,setSelectedExisting]=useState<string>(),[selectedActions,setSelectedActions]=useState<string[]>(['s3:ListBucket']);
 const [customJson,setCustomJson]=useState(defaultPolicy),[jsonMode,setJsonMode]=useState<'visual'|'json'>('visual');
 const [scopeType,setScopeType]=useState<'ALL'|'RESOURCE'|'ARN'>('ALL'),[resourceSearch,setResourceSearch]=useState(''),[resourceService,setResourceService]=useState(''),[resourceRegion,setResourceRegion]=useState(''),[selectedResources,setSelectedResources]=useState<AwsResource[]>([]),[manualArn,setManualArn]=useState('');
 const requestedAt=useMemo(()=>new Date().toISOString(),[]);
 const defaultApprovalBy=useMemo(()=>localDateTime(new Date(Date.now()+24*3600000)),[]);
 const [details,setDetails]=useState({title:'',approvalRequiredBy:defaultApprovalBy,duration:'7 days' as AccessDuration,accessStartMode:'after-approval' as 'after-approval'|'scheduled',scheduledStart:'',customExpiry:'',priority:'Normal' as RequestPriority,approver:'',justification:'',notes:'',permanentAck:false});
 const activeAccountRecordId=session?.user?.activeAwsAccountRecordId??session?.user?.activeAccountId;
 const users=useQuery({queryKey:['users',activeAccountRecordId],queryFn:()=>api.users(),enabled:Boolean(activeAccountRecordId)&&(isUser||isGroup)});
 const roles=useQuery({queryKey:['roles',activeAccountRecordId,includeServiceLinked],queryFn:()=>api.roles('',includeServiceLinked),enabled:Boolean(activeAccountRecordId)&&isRole});
 const groups=useQuery({queryKey:['iam-groups',activeAccountRecordId],queryFn:()=>api.groups(),enabled:Boolean(activeAccountRecordId)&&isGroup&&groupMode==='EXISTING'});
 const selectedGroupDetail=useQuery({queryKey:['iam-group-detail',activeAccountRecordId,target?.name],queryFn:()=>api.group(target!.name),enabled:targetType==='GROUP'&&groupMode==='EXISTING'&&Boolean(target?.name),staleTime:5*60*1000});
 const policies=useQuery({queryKey:['policies','request'],queryFn:()=>api.policies({pageSize:100})});
 const awsResources=useQuery({queryKey:['resources'],queryFn:api.resources});
 const approvers=useQuery({queryKey:['approvers'],queryFn:()=>api.approvers()});
 const context=useQuery({queryKey:['auth-context','request',activeAccountRecordId],queryFn:api.context});
 const activeAccount=context.data?.accounts.find(account=>account.accountRecordId===activeAccountRecordId);
 const steps=isGroup?groupSteps:userRoleSteps,permissionStep=isGroup?3:2,resourcesStep=isGroup?4:3,durationStep=isGroup?5:4,reasonStep=isGroup?6:5,reviewStep=isGroup?7:6;
 const selectedGroupResolved=selectedGroupDetail.data?.arn===target?.arn?selectedGroupDetail.data:undefined;
 const selectedGroupLoading=Boolean(isGroup&&groupMode==='EXISTING'&&target&&!selectedGroupResolved&&selectedGroupDetail.isFetching);
 const selectedGroupError=Boolean(isGroup&&groupMode==='EXISTING'&&target&&selectedGroupDetail.error&&!selectedGroupResolved);
 const currentGroupUsers=useMemo(()=>new Set((selectedGroupResolved?.users??[]).map(user=>user.userName)),[selectedGroupResolved]);
 const memberSearchResults=useMemo(()=>fuzzyIdentities((users.data?.data??[]).filter(identity=>identity.type==='USER'&&!currentGroupUsers.has(identity.name)),identitySearch,false),[users.data,identitySearch,currentGroupUsers]);
 const policyValidation=useMutation({mutationFn:(document:Record<string,unknown>)=>api.validatePolicy(document),onSuccess:()=>setToast('Policy validated. Access Analyzer findings are shown in review when available.')});
 const create=useMutation({mutationFn:api.createRequest,onSuccess:async request=>{const submittedRequest=await api.submitRequest(request.id);setSubmitted(submittedRequest);setToast(`Request ${submittedRequest.id} submitted for approval.`);await Promise.all([qc.invalidateQueries({queryKey:['requests']}),qc.invalidateQueries({queryKey:['activity']})])}});
 const preselected=params.get('policyArn');
 const preselectedTargetType=params.get('targetType') as TargetType|null,preselectedTargetName=params.get('targetName'),preselectedTargetArn=params.get('targetArn');

 useEffect(()=>{const policy=(policies.data?.data??[]).find(item=>item.arn===preselected);if(policy&&!selectedPolicies.some(item=>item.arn===policy.arn))setSelectedPolicies([policy])},[policies.data,preselected,selectedPolicies]);
 useEffect(()=>{if(preselectedTargetType&&['USER','ROLE','GROUP'].includes(preselectedTargetType)&&targetType!==preselectedTargetType){setTargetType(preselectedTargetType);if(preselectedTargetType==='GROUP')setGroupMode('EXISTING')}},[preselectedTargetType,targetType]);
 useEffect(()=>{setTarget(undefined);setIdentitySearch('');setSelectedMembers([]);setGroupName('');if(targetType)setMaxUnlocked(current=>Math.min(current,2))},[targetType]);
 useEffect(()=>{if(groupMode==='CREATE')setTarget(undefined);else setGroupName('')},[groupMode]);
 useEffect(()=>{if(step>2&&!target&&!isGroup)setMaxUnlocked(current=>Math.min(current,2))},[target,step,isGroup]);
 useEffect(()=>{panelRef.current?.scrollIntoView({behavior:'smooth',block:'start'});window.setTimeout(()=>panelRef.current?.querySelector('h2')?.focus(),80)},[step]);
 useEffect(()=>{if(!details.approver&&approvers.data?.[0])setDetails(current=>({...current,approver:approvers.data[0].name}))},[approvers.data,details.approver]);
 useEffect(()=>{if(jsonMode==='visual')setCustomJson(JSON.stringify(buildVisualPolicy(),null,2))},[selectedActions,scopeType,selectedResources,manualArn,jsonMode]);

 const identities=targetType==='USER'?users.data?.data??[]:targetType==='ROLE'?roles.data?.data??[]:targetType==='GROUP'?groups.data?.data??[]:[];
 useEffect(()=>{if(!preselectedTargetType||!preselectedTargetName||target?.name===preselectedTargetName)return;const match=identities.find(identity=>identity.name===preselectedTargetName||identity.arn===preselectedTargetArn);if(match)setTarget(match)},[identities,preselectedTargetType,preselectedTargetName,preselectedTargetArn,target?.name]);
 const identityError=targetType==='USER'?users.error:targetType==='ROLE'?roles.error:targetType==='GROUP'?groups.error:undefined;
 const identityLoading=targetType==='USER'?users.isLoading:targetType==='ROLE'?roles.isLoading:targetType==='GROUP'?groups.isLoading:false;
 const filteredIdentities=useMemo(()=>fuzzyIdentities(identities,identitySearch,includeServiceLinked),[identities,identitySearch,includeServiceLinked]);
 const allPolicies=policies.data?.data??[];
 const existingPolicyArns=new Set((selectedGroupResolved?.attachedPolicies??[]).map(policy=>policy.policyArn));
 const filteredPolicies=useMemo(()=>{
  let list=fuzzyPolicies(allPolicies,policySearch);
  if(serviceFilter)list=list.filter(policy=>policy.services.includes(serviceFilter));
  if(accessFilter)list=list.filter(policy=>policy.accessLevels.includes(accessFilter));
  if(riskFilter)list=list.filter(policy=>policy.risk.level===riskFilter);
  return list;
 },[allPolicies,policySearch,serviceFilter,accessFilter,riskFilter]);
 const serviceOptions=[...new Set(allPolicies.flatMap(policy=>policy.services))].filter(Boolean);
 const accessOptions=[...new Set(allPolicies.flatMap(policy=>policy.accessLevels))].filter(Boolean);
 const relevantServices=selectedPolicies.length?selectedPolicies.flatMap(policy=>policy.services):selectedActions.map(action=>action.split(':')[0]??'');
 const filteredResources=useMemo(()=>{
  let list=fuzzyResources(awsResources.data??[],resourceSearch);
  if(resourceService)list=list.filter(resource=>resource.service===resourceService);
  if(resourceRegion)list=list.filter(resource=>resource.region===resourceRegion);
  if(relevantServices.includes('s3'))list.sort((a,b)=>(a.service==='S3'?-1:0)-(b.service==='S3'?-1:0));
  if(relevantServices.includes('lambda'))list.sort((a,b)=>(a.service==='Lambda'?-1:0)-(b.service==='Lambda'?-1:0));
  if(relevantServices.includes('rds'))list.sort((a,b)=>(a.service==='RDS'?-1:0)-(b.service==='RDS'?-1:0));
  return list;
 },[awsResources.data,resourceSearch,resourceService,resourceRegion,relevantServices.join('|')]);
 const policyJsonValidation=validatePolicyJson(customJson);
 const arnValidation=validateArnList(manualArn,relevantServices.filter(Boolean));
 const accessStartIso=details.accessStartMode==='scheduled'&&details.scheduledStart?new Date(details.scheduledStart).toISOString():new Date().toISOString();
 const expiresAt=calculateExpiry(details.duration,accessStartIso,details.customExpiry);
 const validation=validateAll();
 const canNext=step<steps.length?stepValid(step):validation.blocking.length===0;

 function stepValid(n:number){
  if(n===1)return Boolean(activeAccount&&targetType&&(!isGroup||(groupMode==='CREATE'?validGroupName(groupName):(target&&selectedGroupResolved&&!selectedGroupError))));
  if(isGroup&&n===2)return selectedMembers.length>0;
  if(n===permissionStep)return (!isGroup||Boolean(groupTarget()))&&selectedPermissionItems().length>0&&(!customModeActive()||policyJsonValidation.valid);
  if(n===resourcesStep)return scopeType==='ALL'||(scopeType==='RESOURCE'&&selectedResources.length>0)||(scopeType==='ARN'&&arnValidation.arns.length>0&&arnValidation.errors.length===0);
  if(n===durationStep)return !fieldErrors().some(error=>/duration|expiry|start|approval/i.test(error));
  if(n===reasonStep)return fieldErrors().length===0;
  return true;
 }
 function selectedPermissionItems(){
  if(permissionTab==='AWS_MANAGED')return selectedPolicies.filter(policy=>!existingPolicyArns.has(policy.arn)).map(policy=>({mode:'MANAGED_POLICY' as const,policyName:policy.policyName,policyArn:policy.arn}));
  if(permissionTab==='EXISTING'&&selectedExisting){const policy=target?.attachedPolicies.find(item=>item.policyArn===selectedExisting);return [{mode:'SPECIFIC_ACTIONS' as const,policyName:`Clone ${policy?.policyName??'attached policy'}`,actions:selectedActions,generatedPolicyDocument:buildVisualPolicy()}]}
  if(permissionTab==='CUSTOM'&&policyJsonValidation.document)return [{mode:'SPECIFIC_ACTIONS' as const,actions:selectedActions,generatedPolicyDocument:policyJsonValidation.document as Record<string,unknown>}];
  return [];
 }
 function customModeActive(){return permissionTab==='CUSTOM'||permissionTab==='EXISTING'}
 function buildVisualPolicy(){return {Version:'2012-10-17',Statement:[{Effect:'Allow',Action:selectedActions,Resource:scopeType==='ARN'?arnValidation.arns:scopeType==='RESOURCE'?selectedResources.map(resource=>resource.arn):'*',...(expiresAt&&customModeActive()?{Condition:{DateLessThan:{'aws:CurrentTime':expiresAt}}}:{})}]}}
 function fieldErrors(){const errors:string[]=[];if(details.title.trim().length<5)errors.push('Request title must be at least 5 characters.');const approvalError=validateApprovalDeadline(details.approvalRequiredBy);if(approvalError)errors.push(approvalError);if(details.accessStartMode==='scheduled'&&!details.scheduledStart)errors.push('Scheduled start is required when access starts at a scheduled time.');if(details.scheduledStart&&Date.parse(details.scheduledStart)<Date.parse(requestedAt))errors.push('Scheduled start cannot be earlier than the requested time.');if(details.duration==='Custom'&&!details.customExpiry)errors.push('Custom duration requires an access expiry date and time.');if(details.duration==='Permanent'&&!details.permanentAck)errors.push('Permanent access requires explicit acknowledgement.');if(!details.approver)errors.push('Approver is required.');if(details.justification.trim().length<20)errors.push('Business justification must explain the task and need for access.');return errors}
 function validateAll(){const blocking:string[]=[];if(isGroup){if(!groupTarget())blocking.push(groupMode==='CREATE'?'Enter a valid IAM group name.':'Select an existing IAM group.');if(groupMode==='EXISTING'&&target&&!selectedGroupResolved)blocking.push(selectedGroupError?'Retry loading current group details before continuing.':'Wait for current group details to load.');if(!selectedMembers.length)blocking.push('Select at least one IAM user to add to the group.')}else if(!target)blocking.push('Select an IAM user or role.');if(!selectedPermissionItems().length)blocking.push('Select or build the permissions to request.');if(customModeActive()&&!policyJsonValidation.valid)blocking.push(...policyJsonValidation.errors);if(scopeType==='ARN'&&arnValidation.errors.length)blocking.push(...arnValidation.errors);blocking.push(...fieldErrors());const warnings=[...policyJsonValidation.warnings];if(scopeType==='ALL'&&(riskForPolicies(selectedPolicies)==='High'||riskForPolicies(selectedPolicies)==='Critical'||selectedActions.some(action=>action.endsWith(':*'))))warnings.push('All applicable resources combined with high-risk or wildcard access needs careful review.');if(selectedPolicies.some(policy=>existingPolicyArns.has(policy.arn)))warnings.push('One or more requested policies are already attached to this identity.');if(isGroup&&selectedMembers.length>5)warnings.push('This group request affects multiple users; reviewers should verify the blast radius.');return {blocking,warnings}}
 function submit(){
  const targetIdentity=groupTarget()??target!;
  const payload={title:details.title,targetType:targetType!,targetName:targetIdentity.name,targetArn:targetIdentity.arn,group:isGroup?{mode:groupMode,name:targetIdentity.name}:undefined,members:isGroup?selectedMembers.map(member=>({userName:member.name,userArn:member.arn,operation:'ADD' as const,alreadyMember:currentGroupUsers.has(member.name)})):undefined,items:selectedPermissionItems(),scope:{type:scopeType,resources:selectedResources.map(resource=>resource.name),arn:manualArn||undefined},duration:details.duration,startDate:accessStartIso,expiryDate:expiresAt,priority:details.priority,approver:details.approver,justification:details.justification,notes:details.notes||undefined};
  create.mutate(payload);
 }
 function goBack(){setStep(current=>Math.max(1,current-1))}
 function goNext(){if(!canNext)return;const unlocked=unlockNextWizardStep(step,maxUnlocked,steps.length);setMaxUnlocked(unlocked.nextMaxUnlocked);setStep(unlocked.nextStep)}
 function goToStep(next:number){if(canOpenWizardStep(next,maxUnlocked))setStep(next)}
 function toggleResource(resource:AwsResource){setSelectedResources(current=>current.some(item=>item.arn===resource.arn)?current.filter(item=>item.arn!==resource.arn):[...current,resource])}
 function togglePolicy(policy:IamPolicySummary){setSelectedPolicies(current=>current.some(item=>item.arn===policy.arn)?current.filter(item=>item.arn!==policy.arn):[...current,policy])}
 function toggleAction(action:string){setSelectedActions(current=>current.includes(action)?current.filter(item=>item!==action):[...current,action])}
 function toggleMember(identity:IamIdentity){setSelectedMembers(current=>current.some(item=>item.arn===identity.arn)?current.filter(item=>item.arn!==identity.arn):[...current,identity])}
 function groupTarget():IamIdentity|undefined{if(!isGroup)return undefined;if(groupMode==='EXISTING')return target;if(!validGroupName(groupName)||!activeAccount)return undefined;return {id:`group_${groupName}`,type:'GROUP',name:groupName,arn:`arn:aws:iam::${activeAccount.accountId}:group/permissionhub/${groupName}`,path:'/permissionhub/',createdAt:new Date().toISOString(),description:'New IAM user group requested through PermissionHub',attachedPolicies:[],inlinePolicies:[],users:[],userCount:0}}

 if(submitted)return <div className="page success-page" aria-live="polite"><div className="panel success-panel"><ShieldCheck size={30}/><h1>Request {submitted.id} submitted</h1><p>Your request is now in the approval workflow.</p><dl><div><dt>Target</dt><dd>{submitted.targetType} · {submitted.targetName}</dd></div><div><dt>Requested change</dt><dd>{submitted.items.map((item:any)=>item.policyName??item.actions?.join(', ')).join(', ')}</dd></div><div><dt>Submitted</dt><dd>{formatDate(submitted.submittedAt)}</dd></div></dl><ol className="submission-path"><li className="active"><strong>Account approval</strong><span>Pending</span></li><li><strong>Security review</strong><span>{(submitted.requiredApprovalStages??[]).includes('SECURITY_REVIEWER')?'Not started':'Not required'}</span></li><li><strong>Provisioning</strong><span>Not started</span></li></ol><div className="button-row"><Link className="primary-action" to={`/requests/${submitted.id}`}>View request <ChevronRight size={16}/></Link><Link className="btn btn-secondary" to="/requests">Back to my requests</Link></div></div></div>;

 return <div className="page request-workflow">
  <PageHeader eyebrow="New request" title="Request an IAM permission change" description="Select the identity, permissions, scope, timing and justification. AWS changes are not made until approval and provisioning." />
  {toast&&<div className="toast" role="status"><Check size={15}/>{toast}<button onClick={()=>setToast(undefined)} aria-label="Dismiss notification"><X size={14}/></button></div>}
  <div className="wizard">
   <div className="mobile-step-header" aria-live="polite"><span>Step {step} of {steps.length}</span><strong>{steps[step-1]}</strong><i style={{width:`${(step/steps.length)*100}%`}}/></div>
   <aside className="step-nav" aria-label="Request steps"><ol>{steps.map((label,index)=>{const n=index+1,done=n<maxUnlocked&&stepValid(n),available=canOpenWizardStep(n,maxUnlocked);return <li key={label}><button aria-current={step===n?'step':undefined} className={`${step===n?'active':''} ${done?'done':''} ${!available?'disabled':''}`} onClick={()=>goToStep(n)} disabled={!available}><span>{done?<Check size={14}/>:n}</span><strong>{label}</strong></button></li>})}</ol></aside>
   <section className="panel request-panel" ref={panelRef}>
    {step===1&&<StepSection title="Who needs access?" help="Confirm the selected AWS account, then choose whether access should be attached to an IAM role or legacy IAM user.">
     {activeAccount?<div className="environment-summary"><span><strong>{activeAccount.accountName}</strong><small>{activeAccount.accountId}</small></span><span><strong>{activeAccount.accountType.replaceAll('_',' ')}</strong><small>{activeAccount.environment} · {activeAccount.region}</small></span><span><strong>{activeAccount.connectionStatus}</strong><small>{activeAccount.connectionType.replaceAll('_',' ')}</small></span></div>:<div className="error-panel"><strong>Select an AWS account</strong><span>Use the account selector in the application header before continuing.</span></div>}
     <div className="choice-grid" role="radiogroup" aria-label="Target type">
      <SelectableCard selected={targetType==='ROLE'} icon={<UsersRound/>} title="IAM role or workload" help="Attach permissions to an assumable workload role." onClick={()=>setTargetType('ROLE')}/>
      <SelectableCard selected={targetType==='USER'} icon={<UserRound/>} title="Legacy IAM user" help="Attach permissions directly to a named IAM user." onClick={()=>setTargetType('USER')}/>
      <SelectableCard selected={targetType==='GROUP'} icon={<UsersRound/>} title="IAM user group" help="Group multiple IAM users and manage their permissions together." onClick={()=>setTargetType('GROUP')}/>
     </div>
     {targetType==='GROUP'&&<div className="group-mode-panel"><h3>Group action</h3><div className="choice-grid compact"><SelectableCard selected={groupMode==='CREATE'} icon={<UsersRound/>} title="Create new group" help="Provision a new IAM user group and add selected users." onClick={()=>setGroupMode('CREATE')}/><SelectableCard selected={groupMode==='EXISTING'} icon={<Search/>} title="Update existing group" help="Select an existing IAM group and request additive changes." onClick={()=>setGroupMode('EXISTING')}/></div>{groupMode==='CREATE'?<Field label="Group name" help="Example: DR_DevOps" error={groupName&&!validGroupName(groupName)?'Use a valid IAM group name: letters, numbers and +=,.@-_ only.':undefined}><input value={groupName} onChange={event=>setGroupName(event.target.value)} placeholder="DR_DevOps_Test"/></Field>:<><p className="info-note">Additive only — PermissionHub will add selected users and permissions. Existing group members and policies will not be removed.</p><Toolbar><label className="search-field"><Search size={15}/><input value={identitySearch} onChange={event=>setIdentitySearch(event.target.value)} placeholder="Search IAM groups"/></label><button onClick={()=>groups.refetch()} disabled={groups.isFetching}><RefreshCw size={14}/>{groups.isFetching?'Retrying':'Retry'}</button></Toolbar>{identityLoading&&<SkeletonRows/>}{identityError&&<ErrorPanel title="Unable to load IAM groups" error={groupDiscoveryError(identityError)}/>} {!identityLoading&&!identityError&&!filteredIdentities.length&&<EmptyState title="No IAM groups found" body="Create a new IAM group or choose another AWS account."/>}<div className="identity-table group-table" role="table" aria-label="IAM group selection"><div className="identity-table-head" role="row"><span>Select</span><span>Group name</span><span>Members</span><span>Policies</span><span>Created</span></div>{filteredIdentities.map(identity=>{const selectedRow=target?.arn===identity.arn,detail=selectedRow?selectedGroupResolved:undefined;return <button key={identity.arn} className={selectedRow?'selected':''} onClick={()=>setTarget(identity)} aria-pressed={selectedRow} role="row"><span className={selectedRow?'select-check checked':'select-check'}>{selectedRow&&<Check size={14}/>}</span><strong>{identity.name}<small>{identity.path} · {identity.arn}</small></strong><span>{detail?`${detail.users?.length??0} members`:'—'}</span><span>{detail?`${detail.attachedPolicies.length} policies`:'—'}</span><span>{formatDate(identity.createdAt)}</span></button>})}</div>{target&&<div className="selected-group-card"><div><strong>Selected group</strong><span>{target.name}</span><small>{selectedGroupLoading?'Loading group details…':selectedGroupResolved?`${selectedGroupResolved.users?.length??0} members · ${selectedGroupResolved.attachedPolicies.length} policies`:'Current members and policies required before continuing.'}</small></div>{selectedGroupResolved&&<Button variant="secondary" onClick={()=>setGroupDetailOpen(true)}>View group details</Button>}{selectedGroupError&&<div className="error-panel"><strong>Unable to load group details</strong><span>PermissionHub needs the current members and policies before this group can be updated safely.</span><Button variant="secondary" onClick={()=>selectedGroupDetail.refetch()}>Retry</Button></div>}</div>}<GroupDetailsModal group={target} detail={selectedGroupResolved} loading={selectedGroupLoading} error={selectedGroupError?selectedGroupDetail.error:undefined} open={groupDetailOpen} onClose={()=>setGroupDetailOpen(false)} onRetry={()=>selectedGroupDetail.refetch()}/></>}</div>}
     <p className="muted">Workforce Identity Center targets remain separate from IAM user, role and group targets.</p>
    </StepSection>}

    {isGroup&&step===2&&<StepSection title="Group members" help="Select one or more IAM users to add. Existing group members are shown separately and are not removed.">
     <Toolbar sticky><label className="search-field"><Search size={15}/><input value={identitySearch} onChange={event=>setIdentitySearch(event.target.value)} placeholder="Search IAM users"/></label><button onClick={()=>users.refetch()}><RefreshCw size={14}/>Retry</button></Toolbar>
      <p className="list-count">{selectedMembers.length} selected additions · {(users.data?.data??[]).length} users loaded{currentGroupUsers.size>0&&` · ${currentGroupUsers.size} existing members excluded`}</p>
     {users.isLoading&&<SkeletonRows/>}{users.error&&<ErrorPanel title="Could not load IAM users" error={users.error}/>}
     <div className="identity-table" role="table" aria-label="IAM group member selection"><div className="identity-table-head" role="row"><span>Selection</span><span>Name</span><span>ARN</span><span>Path</span><span>Created</span><span>Current group</span><span>Policies</span></div>{memberSearchResults.map(identity=><button key={identity.arn} className={selectedMembers.some(member=>member.arn===identity.arn)?'selected':''} onClick={()=>toggleMember(identity)} aria-pressed={selectedMembers.some(member=>member.arn===identity.arn)} role="row"><span className={selectedMembers.some(member=>member.arn===identity.arn)?'select-check checked':'select-check'}>{selectedMembers.some(member=>member.arn===identity.arn)&&<Check size={14}/>}</span><strong>{identity.name}</strong><code title={identity.arn}>{identity.arn}</code><span>{identity.path}</span><span>{formatDate(identity.createdAt)}</span><span>{currentGroupUsers.has(identity.name)?'Already member':'Requested add'}</span><span>{identity.attachedPolicies.length} direct</span></button>)}</div>
     <SelectedSummary title="Selected members" items={selectedMembers.map(member=>member.name)}/>
    </StepSection>}

    {step===permissionStep&&<StepSection title={isGroup?'Choose group permissions':'Choose target and permissions'} help={isGroup?'Select one or more managed or custom policies to attach to the IAM group after approval.':'Pick the AWS identity, then select the access to request. Technical policy details remain available without dominating the selection flow.'}>
     {!isGroup&&<><Toolbar><label className="search-field"><Search size={15}/><input value={identitySearch} onChange={event=>setIdentitySearch(event.target.value)} placeholder="Search name, ARN, path or description"/></label>{targetType==='ROLE'&&<label className="check-row"><input type="checkbox" checked={includeServiceLinked} onChange={event=>setIncludeServiceLinked(event.target.checked)}/>Include service-linked roles</label>}<button onClick={()=>targetType==='USER'?users.refetch():roles.refetch()}><RefreshCw size={14}/>Retry</button></Toolbar>
     <p className="list-count">{filteredIdentities.length} {targetType==='USER'?'users':'roles'} loaded{target&&<button onClick={()=>setTarget(undefined)}>Clear selection</button>}</p>
     {identityLoading&&<SkeletonRows/>}
     {identityError&&<ErrorPanel title="Could not load IAM identities" error={identityError}/>}
     {!identityLoading&&!identityError&&!filteredIdentities.length&&<EmptyState title="No identities found" body="Try a different search or include service-linked roles."/>}
     <div className="identity-table" role="table" aria-label={`${targetType==='USER'?'IAM user':'IAM role'} selection`}><div className="identity-table-head" role="row"><span>Selection</span><span>Name</span><span>ARN</span><span>Path</span><span>Created</span><span>{targetType==='USER'?'Console':'Max session'}</span><span>Policies</span></div>{filteredIdentities.map(identity=><button key={identity.arn} className={target?.arn===identity.arn?'selected':''} onClick={()=>setTarget(identity)} aria-pressed={target?.arn===identity.arn} role="row"><span className={target?.arn===identity.arn?'select-check checked':'select-check'}>{target?.arn===identity.arn&&<Check size={14}/>}</span><strong>{identity.name}{identity.description&&<small>{identity.description}</small>}</strong><code title={identity.arn}>{identity.arn}</code><span>{identity.path}</span><span>{formatDate(identity.createdAt)}</span><span>{identity.type==='USER'?`Console: ${identity.passwordEnabled===undefined?'unknown':identity.passwordEnabled?'enabled':'disabled'}`:`${Math.round((identity.maxSessionDuration??0)/60)||'unknown'} min`}</span><span>{identity.attachedPolicies.length} attached</span></button>)}</div></>}
      <h3 className="step-subhead">Select permissions</h3>
      <div className="tabs permission-tabs">{(['AWS_MANAGED','EXISTING','CUSTOM'] as const).map(tab=><button key={tab} className={permissionTab===tab?'active':''} onClick={()=>setPermissionTab(tab)}>{tab==='AWS_MANAGED'?'Managed policies':tab==='EXISTING'?'Existing attached policy':'Custom policy'}</button>)}</div>
     {permissionTab==='AWS_MANAGED'&&<>
      <Toolbar sticky><label className="search-field"><Search size={15}/><input value={policySearch} onChange={event=>setPolicySearch(event.target.value)} placeholder="Search s3 read, lambda execute, cloud wach"/></label><select value={serviceFilter} onChange={event=>setServiceFilter(event.target.value)}><option value="">All services</option>{serviceOptions.map(item=><option key={item}>{item}</option>)}</select><select value={accessFilter} onChange={event=>setAccessFilter(event.target.value)}><option value="">All access</option>{accessOptions.map(item=><option key={item}>{item}</option>)}</select><select value={riskFilter} onChange={event=>setRiskFilter(event.target.value)}><option value="">All risk</option>{['Low','Moderate','High','Critical'].map(item=><option key={item}>{item}</option>)}</select></Toolbar>
      <p className="list-count">{selectedPolicies.length} selected</p>
       <div className="policy-list">{filteredPolicies.slice(0,80).map(policy=><label key={policy.arn} className={selectedPolicies.some(item=>item.arn===policy.arn)?'selected':''}><input type="checkbox" checked={selectedPolicies.some(item=>item.arn===policy.arn)} disabled={existingPolicyArns.has(policy.arn)} onChange={()=>togglePolicy(policy)}/><span><strong>{policy.policyName}</strong><small>{policy.type==='AWS_MANAGED'?'AWS managed':'Customer managed'} · {policy.description}</small><code>{policy.arn}</code></span><em className={`risk ${policy.risk.level.toLowerCase()}`} title={policy.risk.flags.join(', ')||'No broad risk indicators detected'}>{policy.risk.level}</em>{existingPolicyArns.has(policy.arn)&&<b>Already attached</b>}</label>)}</div>
      <SelectedSummary title="Selected policies" items={selectedPolicies.map(policy=>policy.policyName)}/>
     </>}
     {permissionTab==='EXISTING'&&<div className="existing-policy-flow"><p className="warning">AWS-managed policies are immutable. To change one, PermissionHub creates a proposed customer-managed policy based on the selected access instead of modifying AWS-managed policy content.</p><div className="policy-list">{target?.attachedPolicies.map(policy=><label key={policy.policyArn} className={selectedExisting===policy.policyArn?'selected':''}><input type="radio" checked={selectedExisting===policy.policyArn} onChange={()=>setSelectedExisting(policy.policyArn)}/><span><strong>{policy.policyName}</strong><code>{policy.policyArn}</code><small>Managed policy · clone to customer-managed proposal</small></span></label>)}{target?.inlinePolicies.map(policy=><label key={policy} className={selectedExisting===policy?'selected':''}><input type="radio" checked={selectedExisting===policy} onChange={()=>setSelectedExisting(policy)}/><span><strong>{policy}</strong><small>Inline policy · proposed replacement document</small></span></label>)}</div><ActionPicker selected={selectedActions} onToggle={toggleAction}/></div>}
     {permissionTab==='CUSTOM'&&<div className="custom-policy"><div className="tabs"><button className={jsonMode==='visual'?'active':''} onClick={()=>setJsonMode('visual')}>Visual editor</button><button className={jsonMode==='json'?'active':''} onClick={()=>setJsonMode('json')}>JSON editor</button></div>{jsonMode==='visual'&&<ActionPicker selected={selectedActions} onToggle={toggleAction}/>}<label className="field full"><span>Policy JSON</span><textarea className="json-editor" value={customJson} onChange={event=>{setJsonMode('json');setCustomJson(event.target.value)}} spellCheck={false}/></label><div className="button-row"><button onClick={()=>setCustomJson(JSON.stringify(policyJsonValidation.document??JSON.parse(defaultPolicy),null,2))}><FileJson size={14}/>Format</button><button onClick={()=>navigator.clipboard?.writeText(customJson)}>Copy</button><button onClick={()=>setCustomJson(defaultPolicy)}>Reset</button><button onClick={()=>policyJsonValidation.document&&policyValidation.mutate(policyJsonValidation.document as Record<string,unknown>)} disabled={!policyJsonValidation.valid}>Validate with backend</button></div><ValidationList errors={policyJsonValidation.errors} warnings={[...policyJsonValidation.warnings,...((policyValidation.data?.findings??[]).map((finding:any)=>finding.message??finding.issueCode) as string[])]}/></div>}
    </StepSection>}

    {step===resourcesStep&&<StepSection title="Choose resources" help="Specific resources are preferred where discovery supports them. Use all resources only when the permission requires wildcard scope.">
     <div className="choice-grid compact"><SelectableCard selected={scopeType==='ALL'} icon={<ShieldCheck/>} title="All applicable resources" help="Use * or policy-defined resource scope." onClick={()=>setScopeType('ALL')}/><SelectableCard selected={scopeType==='RESOURCE'} icon={<FileKey2/>} title="Specific AWS resource" help="Choose discovered S3, RDS or Lambda resources." onClick={()=>setScopeType('RESOURCE')}/><SelectableCard selected={scopeType==='ARN'} icon={<KeyRound/>} title="Specific ARN" help="Enter one or more ARNs when discovery cannot identify the target." onClick={()=>setScopeType('ARN')}/></div>
     {scopeType==='ALL'&&validation.warnings.some(item=>item.includes('All applicable'))&&<p className="warning">All applicable resources is broad for the selected permissions. Review the risk indicators before submitting.</p>}
     {scopeType==='RESOURCE'&&<><Toolbar sticky><label className="search-field"><Search size={15}/><input value={resourceSearch} onChange={event=>setResourceSearch(event.target.value)} placeholder="Search resource name, ARN, region or tag"/></label><select value={resourceService} onChange={event=>setResourceService(event.target.value)}><option value="">All services</option>{['S3','RDS','Lambda'].map(item=><option key={item}>{item}</option>)}</select><select value={resourceRegion} onChange={event=>setResourceRegion(event.target.value)}><option value="">All regions</option>{[...new Set((awsResources.data??[]).map(resource=>resource.region))].map(item=><option key={item}>{item}</option>)}</select></Toolbar><SelectedSummary title="Selected resources" items={selectedResources.map(resource=>resource.name)}/><div className="resource-grid">{filteredResources.map(resource=><label key={resource.arn} className={selectedResources.some(item=>item.arn===resource.arn)?'selected':''}><input type="checkbox" checked={selectedResources.some(item=>item.arn===resource.arn)} onChange={()=>toggleResource(resource)}/><span><strong>{resource.name}</strong><small>{resource.service} · {resource.region}</small><code>{resource.arn}</code><small>{Object.entries(resource.tags).map(([k,v])=>`${k}: ${v}`).join(' · ')}</small></span></label>)}</div></>}
     {scopeType==='ARN'&&<label className="field full"><span>Specific ARN values</span><textarea value={manualArn} onChange={event=>setManualArn(event.target.value)} placeholder="arn:aws:s3:::finance-reports-dev&#10;arn:aws:s3:::finance-reports-dev/*"/>{arnValidation.errors.map(error=><small className="field-error" key={error}>{error}</small>)}</label>}
    </StepSection>}

    {step===durationStep&&<StepSection title="Choose access duration" help="Temporary access is the default. Permanent access has no automatic expiry and may require additional review.">
     <div className="form-grid labeled"><Field label="Requested on" help="Recorded automatically in ISO format."><input className="readonly-input" value={formatDate(requestedAt)} readOnly/></Field><Field label="Approval required by" error={validateApprovalDeadline(details.approvalRequiredBy)}><input type="datetime-local" min={localDateTime(new Date())} value={details.approvalRequiredBy} onChange={event=>setDetails({...details,approvalRequiredBy:event.target.value})}/></Field><Field label="Access duration" help="Controls how long approved access remains active."><select value={details.duration} onChange={event=>setDetails({...details,duration:event.target.value as AccessDuration})}>{durationOptions.map(item=><option key={item}>{item}</option>)}</select></Field><Field label="Access starts" help="Default is immediately after approval."><select value={details.accessStartMode} onChange={event=>setDetails({...details,accessStartMode:event.target.value as any})}><option value="after-approval">Immediately after approval</option><option value="scheduled">At a scheduled date and time</option></select></Field>{shouldShowScheduledStartInput(details.accessStartMode)?<Field label="Scheduled start" error={details.scheduledStart&&Date.parse(details.scheduledStart)<Date.parse(requestedAt)?'Scheduled start cannot be earlier than the requested time.':undefined}><input type="datetime-local" min={localDateTime(new Date(requestedAt))} value={details.scheduledStart} onChange={event=>setDetails({...details,scheduledStart:event.target.value})}/></Field>:<div className="readonly-field"><span>Scheduled start</span><div>Starts immediately after approval.</div></div>}{details.duration==='Custom'&&<Field label="Access expires" error={!details.customExpiry?'Custom duration requires an expiry.':undefined}><input type="datetime-local" value={details.customExpiry} onChange={event=>setDetails({...details,customExpiry:event.target.value})}/></Field>}<Field label="Calculated expiry"><input className="readonly-input" value={expiresAt?`${formatDate(expiresAt)} — ${details.duration} after access begins.`:'No automatic expiry'} readOnly/></Field></div>{details.duration==='Permanent'&&<label className="warning ack"><input type="checkbox" checked={details.permanentAck} onChange={event=>setDetails({...details,permanentAck:event.target.checked})}/>I acknowledge permanent access has no automatic expiry and requires stronger business justification.</label>}
    </StepSection>}

    {step===reasonStep&&<StepSection title="Why do you need this access?" help="Explain the task, project, or incident requiring access. This is what approvers will read first.">
     <div className="form-grid labeled"><Field label="Request title" help="Example: S3 read access for finance reconciliation" error={details.title&&details.title.length<5?'Use at least 5 characters.':undefined}><input value={details.title} onChange={event=>setDetails({...details,title:event.target.value})} placeholder="S3 read access for finance reconciliation"/></Field><Field label="Priority"><select value={details.priority} onChange={event=>setDetails({...details,priority:event.target.value as RequestPriority})}>{priorityOptions.map(item=><option key={item.value} value={item.value}>{item.value} - {item.hint}</option>)}</select></Field><Field label="Approver" error={!details.approver?'Choose an approver.':undefined}>{approvers.data?.length?<select value={details.approver} onChange={event=>setDetails({...details,approver:event.target.value})}><option value="">Select approver</option>{(approvers.data??[]).map((approver:any)=><option key={approver.id} value={approver.name}>{approver.name}</option>)}</select>:<div className="warning">No approvers are configured in the application data.</div>}</Field><Field label="Business justification" help={`Example: Required to troubleshoot the production API deployment. ${details.justification.length} characters used.`} error={details.justification&&details.justification.length<20?'Provide a stronger justification.':undefined} full><textarea value={details.justification} onChange={event=>setDetails({...details,justification:event.target.value})} placeholder="Required to troubleshoot the production API deployment."/></Field><Field label="Optional notes" full><textarea value={details.notes} onChange={event=>setDetails({...details,notes:event.target.value})}/></Field></div>
    </StepSection>}

    {step===reviewStep&&<StepSection title="Review permission request" help="Resolve blocking validation issues before submission. The proposed AWS operation will run only after approval and provisioning.">
     <div className="readiness"><span className={validation.blocking.length?'status rejected':'status approved'}>{validation.blocking.length?'Not ready':'Ready to submit'}</span>{validation.blocking.length>0&&<ValidationList errors={validation.blocking} warnings={validation.warnings}/>}</div>
     <div className="review-grid"><SummaryCard title="AWS account"><p>{activeAccount?.accountName}</p><small>{activeAccount?.accountType.replaceAll('_',' ')} · {activeAccount?.accountId}</small></SummaryCard><SummaryCard title="Access target"><p>{(groupTarget()??target)?.type} · {(groupTarget()??target)?.name}</p><code>{(groupTarget()??target)?.arn}</code>{isGroup&&<small>{selectedMembers.length} requested member{selectedMembers.length===1?'':'s'} · {groupMode==='CREATE'?'Create group':'Update existing group'}</small>}</SummaryCard><SummaryCard title="Permissions"><p>{selectedPolicies.map(policy=>policy.policyName).join(', ')||selectedActions.join(', ')}</p><RiskBadge risk={riskForPolicies(selectedPolicies)}/></SummaryCard><SummaryCard title="Resources"><p>{scopeType==='ALL'?'All applicable resources':selectedResources.map(resource=>resource.name).join(', ')||arnValidation.arns.join(', ')}</p></SummaryCard><SummaryCard title="Duration"><p>{details.duration}</p><small>Expiry: {expiresAt?formatDate(expiresAt):'Permanent'}</small></SummaryCard><SummaryCard title="Reason"><p>{details.justification}</p><small>{details.priority} · {details.approver}</small></SummaryCard><SummaryCard title="Approval path"><p>{activeAccount?.accountType==='PRODUCTION'?'Account approver → Security review → Provisioning':'Account approver → Provisioning'}</p></SummaryCard>{isGroup&&<SummaryCard title="Group change"><p>{groupMode==='CREATE'?'Create group':'Update existing group'}</p><small>Current: {currentGroupUsers.size} members · {(selectedGroupDetail.data?.attachedPolicies??target?.attachedPolicies??[]).length} policies</small><small>Requested: +{selectedMembers.length} members · +{selectedPolicies.filter(policy=>!existingPolicyArns.has(policy.arn)).length||selectedPermissionItems().length} policies</small></SummaryCard>}</div>
     {customModeActive()&&<TechnicalDetails title="Generated IAM policy" summary={`${selectedActions.length} action${selectedActions.length===1?'':'s'} · ${scopeType==='ALL'?'All resources':scopeType}`}><pre>{JSON.stringify(permissionTab==='CUSTOM'?policyJsonValidation.document:buildVisualPolicy(),null,2)}</pre></TechnicalDetails>}
     {create.isError&&<p className="warning">{readError(create.error)}</p>}<button className="primary-action submit-button" onClick={submit} disabled={create.isPending||validation.blocking.length>0}>{create.isPending?'Submitting request':'Submit request'}</button>
    </StepSection>}

    <footer className="wizard-actions"><button onClick={goBack} disabled={step===1}>Back</button>{step<steps.length&&<button onClick={goNext} disabled={!canNext}>Continue</button>}</footer>
   </section>
  </div>
 </div>;
}

function StepSection({title,help,children}:{title:string;help:string;children:React.ReactNode}){return <div className="step-section"><h2 tabIndex={-1}>{title}</h2><p>{help}</p>{children}</div>}
function Toolbar({children,sticky=false}:{children:React.ReactNode;sticky?:boolean}){return <div className={sticky?'toolbar sticky':'toolbar'}>{children}</div>}
function SelectableCard({selected,icon,title,help,onClick}:{selected:boolean;icon:React.ReactNode;title:string;help:string;onClick:()=>void}){return <button type="button" className={selected?'select-card selected':'select-card'} onClick={onClick} aria-pressed={selected}><span className="select-card-icon">{icon}</span><strong>{title}</strong><small>{help}</small>{selected&&<em><Check size={14}/><span className="sr-only">Selected</span></em>}</button>}
function Field({label,help,error,children,full=false}:{label:string;help?:string;error?:string;children:React.ReactNode;full?:boolean}){return <label className={full?'field full':'field'}><span>{label}</span>{children}{help&&<small>{help}</small>}{error&&<small className="field-error">{error}</small>}</label>}
function ValidationList({errors,warnings}:{errors:string[];warnings:string[]}){return <div className="validation-list" aria-live="polite">{errors.map(error=><p className="field-error" key={error}><AlertTriangle size={14}/>{error}</p>)}{warnings.map(warning=><p className="warning-line" key={warning}><AlertTriangle size={14}/>{warning}</p>)}</div>}
function EmptyState({title,body}:{title:string;body:string}){return <div className="empty-state"><strong>{title}</strong><span>{body}</span></div>}
function ErrorPanel({title,error}:{title:string;error:unknown}){return <div className="error-panel"><strong>{title}</strong><span>{readError(error)}</span></div>}
function SkeletonRows(){return <div className="skeleton-list">{[1,2,3,4].map(item=><i key={item}/>)}</div>}
function SelectedSummary({title,items}:{title:string;items:string[]}){if(!items.length)return null;return <div className="selected-summary"><strong>{title}</strong>{items.map(item=><span key={item}>{item}</span>)}</div>}
function GroupDetailsModal({group,detail,loading,error,open,onClose,onRetry}:{group?:IamIdentity;detail?:IamIdentity;loading:boolean;error:unknown;open:boolean;onClose:()=>void;onRetry:()=>void}){return <Modal open={open&&Boolean(group)} onClose={onClose} title={group?.name??'IAM group details'} subtitle={group?.arn} eyebrow="IAM User Group" closeLabel="Close IAM group details" wide>{!group?<LoadingSkeleton rows={4}/>:<div className="entity-detail"><div className="entity-detail-title"><div><h2>{group.name}</h2><p className="mono wrap-cell">{group.arn}</p></div><div className="entity-badges"><span className="badge badge-info"><i/>IAM Group</span></div></div>{loading?<LoadingSkeleton rows={5}/>:error&&!detail?<div className="error-panel"><strong>Unable to load group details</strong><span>PermissionHub needs the current members and policies before this group can be updated safely.</span><Button variant="secondary" onClick={onRetry}>Retry</Button></div>:<><section className="entity-section"><h3>Overview</h3><dl className="detail-grid"><div><dt>Group name</dt><dd>{group.name}</dd></div><div><dt>ARN</dt><dd className="mono wrap-cell">{group.arn}</dd></div><div><dt>Path</dt><dd>{detail?.path??group.path}</dd></div><div><dt>Created</dt><dd>{formatDate(detail?.createdAt??group.createdAt)}</dd></div><div><dt>Members</dt><dd>{detail?.users?.length??0}</dd></div><div><dt>Policies</dt><dd>{detail?.attachedPolicies.length??0}</dd></div></dl></section><section className="entity-section"><h3>Members</h3>{detail?.users?.length?<div className="chips">{detail.users.map(user=><span key={user.userName}>{user.userName}</span>)}</div>:<p className="muted">No current members reported.</p>}</section><section className="entity-section"><h3>Permissions</h3><div className="entity-list-block"><strong>Managed policies <span>{detail?.attachedPolicies.length??0}</span></strong>{detail?.attachedPolicies.length?<div className="chips">{detail.attachedPolicies.map(policy=><span key={policy.policyArn}>{policy.policyName}</span>)}</div>:<p className="muted">No attached managed policies.</p>}</div><div className="entity-list-block"><strong>Inline policies <span>{detail?.inlinePolicies.length??0}</span></strong>{detail?.inlinePolicies.length?<div className="chips">{detail.inlinePolicies.map(policy=><span key={policy}>{policy}</span>)}</div>:<p className="muted">No inline policies.</p>}</div></section><TechnicalDetails title="Technical details" summary="Raw discovered group metadata"><pre>{JSON.stringify(detail??group,null,2)}</pre></TechnicalDetails><div className="modal-actions"><Button variant="secondary" onClick={onClose}>Close</Button></div></>}</div>}</Modal>}
function ActionPicker({selected,onToggle}:{selected:string[];onToggle:(action:string)=>void}){const [query,setQuery]=useState('');const actions=useMemo(()=>{if(!query)return actionCatalogue;return actionCatalogue.filter(item=>(item.action+item.description+item.keywords.join(' ')).toLowerCase().includes(query.toLowerCase().replace('execute','invoke')))},[query]);return <div className="action-picker"><label className="search-field"><Search size={15}/><input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Search actions by service, name or description"/></label>{actions.map(item=><label key={item.action} className={selected.includes(item.action)?'selected':''}><input type="checkbox" checked={selected.includes(item.action)} onChange={()=>onToggle(item.action)}/><span><strong>{item.action}</strong><small>{item.description}</small></span></label>)}</div>}
function SummaryCard({title,children}:{title:string;children:React.ReactNode}){return <section className="summary-card"><h3>{title}</h3>{children}</section>}
function localDateTime(date:Date){const offset=date.getTimezoneOffset()*60000;return new Date(date.getTime()-offset).toISOString().slice(0,16)}
function formatDate(value?:string){return value?new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(value)):'Unavailable'}
function readError(error:unknown){return (error as any)?.response?.data?.error?.message??(error as Error)?.message??'Action failed.'}
function groupDiscoveryError(error:unknown){const code=(error as any)?.response?.data?.error?.code,status=(error as any)?.response?.status,message=readError(error);if(status===404||code==='NOT_FOUND')return new Error('PermissionHub could not query the IAM group discovery endpoint. Restart the backend after rebuilding and try again.');if(status===403||/AccessDenied|not authorized|not authorised/i.test(message))return new Error('PermissionHub cannot read IAM groups in this AWS account. The discovery role needs iam:ListGroups, iam:GetGroup, iam:ListAttachedGroupPolicies and iam:ListGroupPolicies.');return new Error(message)}
function validGroupName(value:string){return /^[\w+=,.@-]{1,128}$/.test(value)}
